@page "/catalog"
@using sv_e1b0880aa34849bdb459bd2264de95dd.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="container-fluid">
    <div class="row">
        <!-- Filter Sidebar -->
        <div class="col-3">
            <div class="border rounded p-3">
                <h5>Filters</h5>

                @if (categories is not null)
                {
                    <div class="mb-3">
                        <label class="form-label fw-bold">Categories</label>
                        @foreach (var category in categories)
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                                       checked="@selectedCategories.Contains(category)"
                                       @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                                <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                            </div>
                        }
                    </div>
                }

                <div class="mb-3">
                    <label class="form-label fw-bold">Price Range</label>
                    <div class="d-flex gap-2">
                        <input type="number" class="form-control" placeholder="Min" @bind="minPrice" />
                        <input type="number" class="form-control" placeholder="Max" @bind="maxPrice" />
                    </div>
                </div>

                <div class="mb-3 form-check">
                    <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="inStockOnly" />
                    <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                </div>

                <div class="d-flex gap-2">
                    <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
                    <button class="btn btn-outline-secondary" @onclick="ClearFilters">Clear Filters</button>
                </div>
            </div>
        </div>

        <!-- Main Content -->
        <div class="col-9">
            <!-- Toolbar -->
            <div class="d-flex justify-content-between align-items-center mb-3">
                <div>
                    <label class="form-label me-2 mb-0">Sort by:</label>
                    <select class="form-select d-inline-block w-auto" @bind="sortBy" @bind:after="LoadProductsAsync">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A-Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                @if (result is not null)
                {
                    <span class="text-muted">
                        Showing @((result.Page - 1) * result.PageSize + 1)–@(Math.Min(result.Page * result.PageSize, result.TotalCount)) of @result.TotalCount products
                    </span>
                }
            </div>

            <!-- States -->
            @if (isLoading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                    <p class="mt-2">Loading products...</p>
                </div>
            }
            else if (errorMessage is not null)
            {
                <div class="alert alert-danger" role="alert">
                    <strong>Error:</strong> @errorMessage
                </div>
            }
            else if (result is null || result.Items.Count == 0)
            {
                <div class="text-center py-5">
                    <p class="text-muted fs-5">No products found matching your criteria.</p>
                </div>
            }
            else
            {
                <!-- Product Grid -->
                <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
                    @foreach (var product in result.Items)
                    {
                        <div class="col">
                            <div class="card h-100 product-card" @onclick="() => OnProductSelected.InvokeAsync(product.Id)" style="cursor: pointer;">
                                <div class="card-img-top bg-secondary bg-opacity-25 d-flex align-items-center justify-content-center" style="height: 180px;" role="img" aria-label="@product.Name">
                                    <span class="text-muted">@product.Name</span>
                                </div>
                                <div class="card-body">
                                    <h6 class="card-title">@product.Name</h6>
                                    <p class="card-text fw-bold text-primary">@product.Price.ToString("C")</p>
                                    <p class="card-text">@GetStarRating(product.Rating)</p>
                                    @if (!product.InStock)
                                    {
                                        <span class="badge bg-danger">Out of Stock</span>
                                    }
                                </div>
                                <div class="card-footer bg-transparent">
                                    <button class="btn btn-sm btn-success w-100"
                                            disabled="@(!product.InStock)"
                                            @onclick="() => { }" @onclick:stopPropagation="true">
                                        Add to Cart
                                    </button>
                                </div>
                            </div>
                        </div>
                    }
                </div>

                <!-- Pagination -->
                @if (totalPages > 1)
                {
                    <nav class="mt-4" aria-label="Product pagination">
                        <ul class="pagination justify-content-center">
                            <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPage(currentPage - 1)" disabled="@(currentPage == 1)">Previous</button>
                            </li>
                            @for (int i = 1; i <= totalPages; i++)
                            {
                                var pageNum = i;
                                <li class="page-item @(pageNum == currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
                                </li>
                            }
                            <li class="page-item @(currentPage == totalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPage(currentPage + 1)" disabled="@(currentPage == totalPages)">Next</button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        </div>
    </div>
</div>

@code {
    [Parameter]
    public EventCallback<int> OnProductSelected { get; set; }

    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;

    private PagedResult<Product>? result;
    private bool isLoading;
    private string? errorMessage;

    private int totalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            isLoading = true;
            categories = await ProductService.GetCategoriesAsync();
            await LoadProductsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
            isLoading = false;
        }
    }

    private async Task LoadProductsAsync()
    {
        try
        {
            isLoading = true;
            errorMessage = null;

            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await LoadProductsAsync();
    }

    private static string GetStarRating(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

